CREATE COLUMN TABLE "TEST_AP"."OCRG" ("GroupCode" SMALLINT CS_INT NOT NULL , "GroupName" NVARCHAR(100) NOT NULL , "GroupType" NVARCHAR(1) DEFAULT 'C', "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "PriceList" SMALLINT CS_INT, "DiscRel" NVARCHAR(1) DEFAULT 'L', "EffecPrice" NVARCHAR(1) DEFAULT 'D', PRIMARY KEY ("GroupCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OCRG_GROUP_TYPE" ON "TEST_AP"."OCRG" ( "GroupType" ASC );
CREATE UNIQUE INDEX "OCRG_GROUP_NAME" ON "TEST_AP"."OCRG" ( "GroupName" ASC )